const SPECIAL_FLOAT = /^[+-]?(?:inf(?:inity)?|nan)$/i;
const DECIMAL_FLOAT = /^[+-]?(?:(?:\d+(?:\.\d*)?)|(?:\.\d+))(?:[eE][+-]?\d+)?$/;

function formatScientificExponent(exponent) {
  const sign = exponent >= 0 ? '+' : '-';
  const magnitude = String(Math.abs(exponent)).padStart(2, '0');
  return `${sign}${magnitude}`;
}

function formatFixedDigits(digits, exponent) {
  const decimalPoint = exponent + 1;

  if (decimalPoint <= 0) {
    return `0.${'0'.repeat(-decimalPoint)}${digits}`;
  }

  if (decimalPoint >= digits.length) {
    return `${digits}${'0'.repeat(decimalPoint - digits.length)}.0`;
  }

  return `${digits.slice(0, decimalPoint)}.${digits.slice(decimalPoint)}`;
}

function formatScientificDigits(digits, exponent) {
  const coefficient =
    digits.length === 1 ? digits : `${digits[0]}.${digits.slice(1)}`;
  return `${coefficient}e${formatScientificExponent(exponent)}`;
}

export function parsePythonFloatLiteral(rawValue) {
  if (!SPECIAL_FLOAT.test(rawValue) && !DECIMAL_FLOAT.test(rawValue)) {
    return null;
  }

  const parsed = Number(rawValue);
  if (Number.isNaN(parsed) && !/nan/i.test(rawValue)) {
    return null;
  }

  return parsed;
}

export function toPythonFloatString(value) {
  if (Number.isNaN(value)) {
    return 'nan';
  }

  if (value === Infinity) {
    return 'inf';
  }

  if (value === -Infinity) {
    return '-inf';
  }

  if (Object.is(value, -0)) {
    return '-0.0';
  }

  if (Object.is(value, 0)) {
    return '0.0';
  }

  const sign = value < 0 ? '-' : '';
  const absoluteValue = Math.abs(value);
  const match = /^(\d)(?:\.(\d+))?e([+-]?\d+)$/.exec(absoluteValue.toExponential());

  if (match === null) {
    throw new Error('Unable to format float value.');
  }

  const digits = `${match[1]}${match[2] ?? ''}`;
  const exponent = Number(match[3]);

  if (exponent < -4 || exponent >= 16) {
    return `${sign}${formatScientificDigits(digits, exponent)}`;
  }

  return `${sign}${formatFixedDigits(digits, exponent)}`;
}

