import { DecimalValue, decimalFromPythonFloatString } from './decimal.mjs';
import { normalizeAndValidateCurrency } from './currencies.mjs';
import { toPythonFloatString } from './pythonFloat.mjs';

function normalizeAmount(amount) {
  if (amount instanceof DecimalValue) {
    return amount;
  }

  if (typeof amount === 'number') {
    return decimalFromPythonFloatString(toPythonFloatString(amount));
  }

  throw new TypeError('Money amount must be a number.');
}

export class Money {
  constructor(amount, currency) {
    this.amount = normalizeAmount(amount);
    this.currency = normalizeAndValidateCurrency(currency);
  }

  divide(divisor) {
    return new Money(this.amount.divideByInteger(divisor), this.currency);
