import { parsePythonFloatLiteral } from '../money/pythonFloat.mjs';

const OPTIONS = [
  { key: 'help', long: '--help', short: '-h', takesValue: false },
  { key: 'amount', long: '--amount', takesValue: true },
  { key: 'currency', long: '--currency', takesValue: true },
];

const NEGATIVE_NUMBER_TOKEN = /^-\d+$|^-\d*\.\d+$/;

function basename(pathname) {
  const parts = String(pathname ?? '').split(/[\\/]/);
  return parts[parts.length - 1] || 'test6.mjs';
}

function buildUsage(programName) {
  return `usage: ${programName} [-h] --amount AMOUNT --currency CURRENCY`;
}

function buildHelp(programName) {
  return `${buildUsage(programName)}

options:
  -h, --help           show this help message and exit
  --amount AMOUNT
  --currency CURRENCY
`;
}

function exitWithHelp(programName) {
  process.stdout.write(buildHelp(programName));
  process.exit(0);
}

function exitWithParserError(programName, message) {
  process.stderr.write(`${buildUsage(programName)}
${programName}: error: ${message}
`);
  process.exit(2);
}

function resolveLongOption(optionToken, programName) {
  const matches = OPTIONS.filter((option) => option.long.startsWith(optionToken));
  if (matches.length === 1) {
    return matches[0];
  }

  if (matches.length > 1) {
    const choices = matches.map((option) => option.long).join(', ');
    exitWithParserError(
      programName,
      `ambiguous option: ${optionToken} could match ${choices}`,
    );
  }

  return null;
}

function isNegativeNumberToken(token) {
  return NEGATIVE_NUMBER_TOKEN.test(token);
}

function looksLikeOptionToken(token) {
  return token !== undefined && token !== '-' && token.startsWith('-') && !isNegativeNumberToken(token);
}

function parseAmountValue(value, programName) {
  const parsed = parsePythonFloatLiteral(value);
  if (parsed === null) {
    exitWithParserError(programName, `argument --amount: invalid float value: '${value}'`);
  }
  return parsed;
}

function assignOptionValue(state, option, rawValue, programName) {
  if (option.key === 'amount') {
    state.amount = parseAmountValue(rawValue, programName);
    return;
  }

  if (option.key === 'currency') {
    state.currency = rawValue;
  }
}

function consumeOptionValue(argv, index, option, programName) {
  const nextToken = argv[index + 1];
  if (nextToken === undefined || nextToken === '--' || looksLikeOptionToken(nextToken)) {
    exitWithParserError(programName, `argument ${option.long}: expected one argument`);
  }
  return nextToken;
}

function handleShortHelpToken(token, programName) {
  if (token === '-h' || (token.startsWith('-h') && !token.startsWith('-h='))) {
    exitWithHelp(programName);
  }

  if (token.startsWith('-h=')) {
    exitWithParserError(
      programName,
      `argument -h/--help: ignored explicit argument '${token.slice(3)}'`,
    );
  }
}

export function getProgramName(scriptPath) {
  return basename(scriptPath);
}

export function parseCliArguments(argv, programName) {
  const state = {
    amount: undefined,
    currency: undefined,
  };
  const extras = [];
  let stopParsingOptions = false;

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (stopParsingOptions) {
      extras.push(token);
      continue;
    }

    if (token === '--') {
      stopParsingOptions = true;
      continue;
    }

    if (token.startsWith('--')) {
      const equalsIndex = token.indexOf('=');
      const optionToken = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
      const explicitValue = equalsIndex === -1 ? null : token.slice(equalsIndex + 1);
      const option = resolveLongOption(optionToken, programName);

      if (option === null) {
        extras.push(token);
        continue;
      }

      if (option.key === 'help') {
        if (explicitValue !== null) {
          exitWithParserError(
            programName,
            `argument -h/--help: ignored explicit argument '${explicitValue}'`,
          );
        }
        exitWithHelp(programName);
      }

      if (explicitValue !== null) {
        assignOptionValue(state, option, explicitValue, programName);
        continue;
      }

      const value = consumeOptionValue(argv, index, option, programName);
      assignOptionValue(state, option, value, programName);
      index += 1;
      continue;
    }

    if (token.startsWith('-')) {
      handleShortHelpToken(token, programName);
      extras.push(token);
      continue;
    }

    extras.push(token);
  }

  const missing = [];
  if (state.amount === undefined) {
    missing.push('--amount');
  }
  if (state.currency === undefined) {
    missing.push('--currency');
  }

  if (missing.length > 0) {
    exitWithParserError(
      programName,
      `the following arguments are required: ${missing.join(', ')}`,
    );
  }

  if (extras.length > 0) {
    exitWithParserError(programName, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return state;
}

